//  LagumisaRefrainStore.swift
//  BibleApp
//
//  Loads the bundled lagumisa_refrains.json file and provides fast
//  slug → refrain text lookups. Fully offline — no network required.
//
//  The JSON file is generated by scripts/scrape_lagumisa.py and
//  must be added to the Xcode target's "Copy Bundle Resources" phase.

import Foundation

final class LagumisaRefrainStore {

    static let shared = LagumisaRefrainStore()

    /// slug (e.g. "a-minggu-adven-1") → Indonesian sung refrain text
    private let data: [String: String]

    private init() {
        guard
            let url  = Bundle.main.url(forResource: "lagumisa_refrains", withExtension: "json"),
            let raw  = try? Data(contentsOf: url),
            let dict = try? JSONDecoder().decode([String: String].self, from: raw)
        else {
            data = [:]
            return
        }
        data = dict
    }

    /// Returns the sung refrain for the given lagumisa slug, or nil if not found.
    func refrain(for slug: String) -> String? {
        data[slug]
    }
}
